"""Hatchery art (your painted egg-room sheet): background, egg frames, iron cradle, the five rarity eggs.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

PLATE = (0.115, 0.755, 0.885, 0.935)     # brass plate inside the egg frame (fractions of the frame)
LIGHTS = ((508, 140, 46), (1358, 140, 46), (148, 510, 40), (1808, 270, 46), (1840, 492, 38))   # torches, lanterns, fire bowl in hatch_bg.jpg
PNG = {
  'egg_common': ('png', ''),
  'egg_cradle': ('png', ''),
  'egg_epic': ('png', ''),
  'egg_frame': ('png', ''),
  'egg_frame_gold': ('png', ''),
  'egg_legendary': ('png', ''),
  'egg_rare': ('png', ''),
  'egg_uncommon': ('png', ''),
  'hatch_bg': ('jpg', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
